-- BattleTech planetary systems, Era 3052, with descriptions and image references.
-- Source coordinates and political affiliation: Sarna Unified Cartography Kit (SUCKit) Systems CSV export.
-- IMPORTANT: SUCKit does not provide ecosystem classifications.
-- 'earth.png' is a neutral/unclassified fallback for systems without verified ecosystem data.
-- A small number of well-known worlds have best-effort broad visual classifications.

CREATE TABLE IF NOT EXISTS planets (
    planet TEXT NOT NULL,
    x REAL,
    y REAL,
    controller TEXT,
    description TEXT,
    image TEXT NOT NULL DEFAULT 'earth.png' CHECK (image IN ('ocean.png', 'purple.png', 'desert.png', 'earth.png', 'forest.png', 'gas.png', 'lava.png', 'dust.png'))
);


-- Imported systems: 3175
